import kotlinx.coroutines.*

suspend fun chajeDone(): String = withContext(Dispatchers.IO) {
    delay(300)
    "Done sou rezo"
}

fun main() = runBlocking {
    val t1 = async { chajeDone() }
    val t2 = async { chajeDone() }
    println(t1.await() + " + " + t2.await())
}

import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*

fun konte(): Flow<Int> = flow {
    for (i in 1..3) {
        delay(200)
        emit(i)
    }
}

fun main() = runBlocking {
    konte().map { it * 10 }.collect { println(it) }
}

